# Bám sách: trang 84–85 + đáp án + Mini dictionary unit 40. Không chép nguyên văn.
theory = (
 H("A", "Talking about negative qualities", "Nói về tính cách xấu")
 + P("Leah and Naomi talk about their friend Natasha’s new boyfriend.", "Leah và Naomi bàn về bạn trai mới của Natasha.")
 + T([
    ("<b>be getting on</b> / <b>bore into</b>", "(informal, always continuous) He is getting old; his eyes looked at Naomi so hard that she felt uncomfortable.", "(thân mật, luôn tiếp diễn) Anh ta đã có tuổi; ánh mắt anh ta nhìn xoáy vào Naomi khiến cô khó chịu."),
    ("<b>descend to</b>", "Leah would not behave as badly as him by answering back.", "Leah không hạ mình cãi lại cho bằng anh ta."),
    ("<b>screw up</b> / <b>have</b> sb <b>down as</b>", "(informal) Having such a brother would make anyone confused and unhappy; Leah thought Natasha was sensible.", "(thân mật) Có ông anh như thế ai cũng rối trí; Leah vốn cho Natasha là người biết điều."),
    ("<b>grow out of</b>", "Natasha should stop needing a father figure now that she is older.", "Natasha nên thôi cần hình bóng người cha khi đã lớn."),
    ("<b>toughen up</b> / <b>outspoken</b>", "Naomi tells Leah to become stronger (also transitive: toughen sb up); the boyfriend says what he thinks even if it offends.", "Naomi bảo Leah cứng rắn lên (cũng dùng có tân ngữ: toughen sb up); gã bạn trai nói thẳng dù làm người khác phật lòng."),
 ])
 + H("B", "Talking about positive qualities", "Nói về phẩm chất tốt")
 + P("A manager’s speech at a party for a retiring colleague, Jack.", "Bài phát biểu của một giám đốc trong buổi tiệc chia tay đồng nghiệp nghỉ hưu, Jack.")
 + T([
    ("<b>vouch for</b>", "The manager can promise that Jack has been loyal and skilled.", "Giám đốc có thể đảm bảo Jack trung thành và giỏi giang."),
    ("<b>shine through</b> / <b>pride yourself on</b>", "His ability to handle people became clear from the start; he took pride in good relations with junior staff (see Unit 27).", "Khả năng quản lý con người của ông lộ rõ ngay từ đầu; ông tự hào về quan hệ tốt với nhân viên cấp dưới (xem bài 27)."),
    ("<b>light up</b>", "His face looked very happy whenever he solved a hard problem.", "Mặt ông rạng rỡ mỗi khi giải quyết được vấn đề khó."),
    ("<b>draw out</b> / <b>bring out</b>", "He helped younger staff feel more confident and made his colleagues’ best qualities more noticeable.", "Ông giúp nhân viên trẻ tự tin hơn và khơi dậy điểm mạnh của đồng nghiệp."),
    ("<b>come across</b> (as)", "He always appeared calm, professional and committed.", "Ông luôn tỏ ra điềm tĩnh, chuyên nghiệp và tận tâm."),
 ])
 + NOTE("<b>Tip</b> (from the book): a phrasal verb’s meaning can change depending on whether it has an object – <b>come across</b> without an object = seem to be; with an object = find or meet by chance (an old photo). Note verbs that change like this.",
        "<b>Mẹo</b> (của sách): nghĩa của phrasal verb có thể đổi tùy có tân ngữ hay không – <b>come across</b> không tân ngữ = tỏ ra; có tân ngữ = tình cờ thấy, gặp (một tấm ảnh cũ). Hãy ghi lại những động từ đổi nghĩa như vậy.")
)
